import java.util.ArrayList;
import java.util.List;

public class Main {
    interface Listener {
        void onPriceChange(String stock, int price);
    }

    static class Market {
        private final List<Listener> listeners = new ArrayList<>();

        void subscribe(Listener listener) {
            listeners.add(listener);
        }

        void setPrice(String stock, int price) {
            for (Listener listener : listeners) {
                listener.onPriceChange(stock, price);
            }
        }
    }

    static class Person implements Listener {
        private final String name;

        Person(String name) {
            this.name = name;
        }

        public void onPriceChange(String stock, int price) {
            System.out.println(name + " sees " + stock + " at " + price);
        }
    }

    public static void main(String[] args) {
        Market market = new Market();
        market.subscribe(new Person("Alice"));
        market.subscribe(new Person("Bob"));
        market.setPrice("ACME", 120);
    }
}
